import{_ as a,o as i,c as t,ag as o}from"./chunks/framework.cyF4XceO.js";const f=JSON.parse('{"title":"Form Definition profiles","description":"","frontmatter":{},"headers":[],"relativePath":"spec/form-definition/index.md","filePath":"spec/form-definition/index.md"}'),s={name:"spec/form-definition/index.md"};function n(r,e,d,c,l,p){return i(),t("div",null,[...e[0]||(e[0]=[o(`<h1 id="form-definition-profiles" tabindex="-1">Form Definition profiles <a class="header-anchor" href="#form-definition-profiles" aria-label="Permalink to &quot;Form Definition profiles&quot;">​</a></h1><p>A Form Definition is a deterministic, data-only description of one portable service shape. Requirement keywords are used as described in <a href="./../conformance.html"><code>../conformance.md</code></a>.</p><p>The current family profile is <a href="/schemas/v1beta1/form-definition.schema.json"><code>form-definition-v1beta1.schema.json</code></a> with <a href="/schemas/v1beta1/form-ref.schema.json"><code>form-ref-v1beta1.schema.json</code></a>: its <code>apiVersion</code> is a namespaced Form Family group (<a href="./../decisions/0009-form-families-and-namespaced-api-versions.html">decision 0009</a>), it declares a required closed <code>role</code> (identity/revision/deployment/attachment/policy), it references exact Interface and Binding contracts (<code>providedInterfaces</code>, <code>acceptedBindings</code>), its desired schema never contains a <code>name</code> property (the wire envelope owns <code>metadata.name</code> — <a href="./../decisions/0011-resource-identity-generation-and-revision.html">decision 0011</a>), and free semantic tokens are prohibited (<a href="./../decisions/0008-forms-preserve-service-shape.html">decision 0008</a>).</p><p>The retained <code>forms.takoform.com/v1alpha2</code> Draft 2020-12 schemas are <a href="../../formpackage/schemas/form-definition-v1alpha2.schema.json"><code>form-definition-v1alpha2.schema.json</code></a> and <a href="../../formpackage/schemas/form-ref-v1alpha2.schema.json"><code>form-ref-v1alpha2.schema.json</code></a>. The unversioned filenames <a href="../../formpackage/schemas/form-definition.schema.json"><code>form-definition.schema.json</code></a> and <a href="../../formpackage/schemas/form-ref.schema.json"><code>form-ref.schema.json</code></a> are retained v1alpha1 Legacy profiles, not aliases for the retained v1alpha2 or current family profiles.</p><h2 id="exact-formref" tabindex="-1">Exact FormRef <a class="header-anchor" href="#exact-formref" aria-label="Permalink to &quot;Exact FormRef&quot;">​</a></h2><p>The immutable reference to a definition is exactly these four fields, with no extensions:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;apiVersion&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;edge.forms.takoform.com/v1beta1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;kind&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ExampleStore&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;definitionVersion&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0.1.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;schemaDigest&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;sha256:&lt;64 lowercase hexadecimal characters&gt;&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>kind</code> MUST be a PascalCase portable kind, <code>definitionVersion</code> MUST be SemVer, and <code>schemaDigest</code> MUST be SHA-256 over the definition&#39;s RFC 8785 canonical bytes. The definition MUST repeat the first three identity fields, and a verifier MUST reject any mismatch.</p><h2 id="definition-fields" tabindex="-1">Definition fields <a class="header-anchor" href="#definition-fields" aria-label="Permalink to &quot;Definition fields&quot;">​</a></h2><p>A definition contains:</p><ul><li>the three non-digest identity fields;</li><li>a title and optional description;</li><li>inline Draft 2020-12 desired and observed schemas, plus an optional output schema;</li><li>optional immutable JSON Pointer fields;</li><li>an explicit subset of <code>create</code>, <code>read</code>, <code>update</code>, <code>delete</code>, <code>import</code>, and <code>observe</code> — the current family&#39;s whole capability vocabulary. <code>refresh</code> and <code>drift</code> belong to the withdrawn lanes and no current schema admits them; the open <code>(name, version)</code> Interface descriptors of the withdrawn v1alpha2 profile are replaced by exact digest-bound <code>providedInterfaces</code> (<a href="./../interface-contract/"><code>../interface-contract/</code></a>);</li><li>optional references to data-only positive desired/observed/output fixtures and negative schema fixtures in the same package, with independent maxima of 32 positive fixtures and 32 negative fixtures.</li></ul><p>The current family structure deliberately has no maturity or deprecation field. Proposal, Experimental, Stable, and Legacy state is owned outside the immutable definition as defined in <a href="./../project-lifecycle.html"><code>../project-lifecycle.md</code></a>. This keeps one mutable authority for a fact that can change while immutable Definition bytes cannot.</p><p>Published v1alpha1 Definitions retain their historical document-local <code>compatibility-candidate</code>, <code>standard</code>, or <code>deprecated</code> field. A verifier MUST preserve those bytes, but current tooling MUST NOT infer maturity from them or copy the field into a current family definition.</p><p>Negative fixtures name their validation stage. Host Support evidence executes <code>desired</code> negatives in the host role; provider compatibility evidence executes <code>desired</code> and <code>observed</code> negatives before state projection. <code>output</code> remains a valid package-structure validation stage, but a conformance claim fails closed on it until a portable runner contract defines how its role executes that case.</p><p>The published Form Definition JSON Schema is a normative structural minimum. The semantic verifier rules below are also normative: document-local reference closure, closed-object proof, validation-work limits, fixture semantics, and the portable data-only vocabulary can reject a document that satisfies the outer JSON Schema.</p><h2 id="connections-were-the-withdrawn-profile-s-surface" tabindex="-1">Connections were the withdrawn profile&#39;s surface <a class="header-anchor" href="#connections-were-the-withdrawn-profile-s-surface" aria-label="Permalink to &quot;Connections were the withdrawn profile&#39;s surface&quot;">​</a></h2><p>The <code>connections</code> map — request-only permission/projection tokens naming another Resource — was the withdrawn v1alpha2 profile&#39;s capability surface. The current family replaces it end to end with exact digest-bound typed Bindings (<a href="./../binding-contract/"><code>../binding-contract/</code></a>) and uid-pinned relations (<a href="./../decisions/0015-cross-resource-references-are-uid-pinned-relations.html">decision 0015</a>, <a href="./../decisions/0022-relations-pin-the-target-contract.html">decision 0022</a>); no current Definition declares <code>connections</code>, and the withdrawn semantics stay in git history with their profile.</p><h2 id="digest-bound-artifact-sources" tabindex="-1">Digest-bound artifact sources <a class="header-anchor" href="#digest-bound-artifact-sources" aria-label="Permalink to &quot;Digest-bound artifact sources&quot;">​</a></h2><p>An artifact-backed Form of the current family declares its bytes as ONE member: the content-addressed manifest digest committed through the artifact-transport upload API (<a href="./../decisions/0012-artifacts-use-content-addressed-upload.html">decision 0012</a>, <a href="./../artifact-transport/"><code>../artifact-transport/</code></a>). No URL enters desired state — where bytes are fetched from is a host fact, and the digest alone says which bytes. The withdrawn v1alpha2 profile&#39;s <code>artifactUrl</code>/<code>artifactSha256</code>/<code>artifactMediaType</code> source object and its credential-free-HTTPS grammar stay in git history with that profile.</p><p>Object schemas are closed by default and MUST set <code>&quot;additionalProperties&quot;: false</code>. A pure typed map is the only open-key escape. It must explicitly use <code>&quot;type&quot;: &quot;object&quot;</code>, must not mix fixed or dependent properties, must reject <code>patternProperties</code>, and must use a schema for <code>additionalProperties</code> plus this exact key policy:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;propertyNames&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;string&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;pattern&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;^[A-Za-z][A-Za-z0-9._-]{0,63}$&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;x-takoform-fieldPolicy&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;portable-data-only-v1&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>The marker is a host conformance requirement, not an annotation to ignore: map keys are checked with the same portable data-only forbidden-field policy as declared fields. <code>additionalProperties: true</code>, an omitted <code>additionalProperties</code>, a permissive or unmarked <code>propertyNames</code>, and <code>patternProperties</code> are rejected.</p><p>This rule applies at every nested schema node, not only at the desired or observed root. Boolean <code>false</code> is safe because it accepts no value; boolean <code>true</code>, <code>{}</code>, an implicit schema such as <code>{&quot;not&quot;:{&quot;type&quot;:&quot;string&quot;}}</code>, and object keywords such as <code>minProperties</code> without an explicit closed <code>type: object</code> are rejected because each can admit arbitrary objects. <code>allOf</code>/<code>anyOf</code>/<code>oneOf</code> and local <code>$ref</code> remain usable only when every relevant branch or resolved target proves that objects are excluded or closed. A non-object <code>type</code> is the normal proof for primitive and array schemas. Arrays must additionally declare <code>items</code> (a safe schema or <code>false</code>) so omitted item constraints cannot reintroduce arbitrary nested objects; tuple <code>prefixItems</code> do not remove that requirement for trailing items.</p><h2 id="hard-boundary" tabindex="-1">Hard boundary <a class="header-anchor" href="#hard-boundary" aria-label="Permalink to &quot;Hard boundary&quot;">​</a></h2><p>Definitions and every JSON payload are recursively checked for credential, secret, token, account, operator, target/pool, capacity, backend manager, provider config, price, SKU, billing, quota, SLA/support policy, executable, command, script, source/adapter/validation/runtime code, WebAssembly, and plugin fields. This policy is intentionally fail-closed. A host-owned implementation, placement, commercial configuration, or executable extension is not portable Form Definition data.</p><p>The check is structural: normalized exact names, exact camelCase, snake_case, or kebab-case tokens, and reviewed token sequences such as <code>api</code> + <code>key</code>, <code>private</code> + <code>key</code>, <code>service</code> + <code>offering</code>, and <code>manager</code> + <code>identifier</code> are compared with a forbidden vocabulary. Glued lowercase spellings are limited by exact reviewed compound-base and qualifier pairs such as <code>apikey</code> + <code>material</code>; the policy does not use arbitrary substring matching. Standard schema keys such as <code>description</code>, and prose values that discuss authentication, API keys, service offerings, or billing, remain valid; fields such as <code>authorization</code>, <code>oauthClient</code>, <code>sessionCookie</code>, <code>apiKeyValue</code>, <code>privateKeyPem</code>, <code>invoice</code>, <code>paymentMethod</code>, <code>currency</code>, <code>taxCode</code>, <code>serviceOfferingId</code>, <code>managerIdentifier</code>, and <code>region</code> do not.</p><p>Every package is an exact one-definition package, never one multi-definition package. The current generated catalog and package set predate decision <a href="./../decisions/0004-takoform-is-an-experimental-specification.html"><code>0004</code></a>: their <code>status: standard</code>, <code>structural-candidate</code>, and <code>portable-standard</code> values are retained Legacy document facts, not a current maturity hierarchy. Host Support and provider compatibility evidence are supplied by their owning implementations and are not synthesized by the package generator.</p>`,27)])])}const m=a(s,[["render",n]]);export{f as __pageData,m as default};
